class Matrix3D {
private:
    int n;
    set<tuple<int, int, int>> ones;
    vector<int> count;
    priority_queue<pair<int, int>> pq;

public:
    Matrix3D(int n) : n(n), count(n, 0) {
        for (int x = 0; x < n; ++x) {
            pq.push({0, x});
        }
    }

    void setCell(int x, int y, int z) {
        if (!ones.contains({x, y, z})) {
            ones.insert({x, y, z});
            count[x]++;
            pq.push({count[x], x});
        }
    }

    void unsetCell(int x, int y, int z) {
        if (ones.contains({x, y, z})) {
            ones.erase({x, y, z});
            count[x]--;
            pq.push({count[x], x});
        }
    }

    int largestMatrix() {
        while (!pq.empty()) {
            auto [c, x] = pq.top();
            if (c == count[x]) return x;
            pq.pop();
        }
        return 0;
    }
};

class Matrix3D {
    private int n;
    private Set<String> ones;
    private int[] count;
    private PriorityQueue<int[]> pq;

    public Matrix3D(int n) {
        this.n = n;
        this.ones = new HashSet<>();
        this.count = new int[n];
        this.pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(b[1], a[1]));
        for (int x = 0; x < n; ++x) {
            pq.offer(new int[]{0, x});
        }
    }

    public void setCell(int x, int y, int z) {
        String key = x + "," + y + "," + z;
        if (ones.add(key)) {
            count[x]++;
            pq.offer(new int[]{count[x], x});
        }
    }

    public void unsetCell(int x, int y, int z) {
        String key = x + "," + y + "," + z;
        if (ones.remove(key)) {
            count[x]--;
            pq.offer(new int[]{count[x], x});
        }
    }

    public int largestMatrix() {
        while (!pq.isEmpty()) {
            int[] top = pq.peek();
            if (top[0] == count[top[1]]) return top[1];
            pq.poll();
        }
        return 0;
    }
}

var Matrix3D = function(n) {
    this.n = n;
    this.ones = new Set();
    this.count = new Int32Array(n);
};

Matrix3D.prototype.setCell = function(x, y, z) {
    const key = `${x},${y},${z}`;
    if (!this.ones.has(key)) {
        this.ones.add(key);
        this.count[x]++;
    }
};

Matrix3D.prototype.unsetCell = function(x, y, z) {
    const key = `${x},${y},${z}`;
    if (this.ones.has(key)) {
        this.ones.delete(key);
        this.count[x]--;
    }
};

Matrix3D.prototype.largestMatrix = function() {
    let bestCount = -1;
    let bestLayer = 0;
    for (let x = 0; x < this.n; x++) {
        if (this.count[x] >= bestCount) {
            bestCount = this.count[x];
            bestLayer = x;
        }
    }
    return bestLayer;
};
